+    int     by_eol;
+    int	    rollback = 0;
+    int     line_size;
+    int     i;
+    char   *s2;
+    char    tmp_str[3];

     /*
      * This is implemented as a simple state machine of five states.
@@ -1266,6 +1278,7 @@ parse_token (token_t token, char *str)
                 /* New packet starts here */
                 start_new_packet(FALSE);
                 state = READ_OFFSET;
